using Notifications.Legacy;

namespace Notifications;

/// <summary>Sends push notifications.</summary>
public sealed class PushClient
{
    public bool SendPush(Message message)
    {
#pragma warning disable CS0618 // No replacement API is present in the supplied context.
        return PushApiV1.Push(message.Recipient.Name, message.Body);
#pragma warning restore CS0618
    }
}
